// src/builder/rule.ts
var RULE_CHAR = {
  HYPHEN: "-",
  ASTERISK: "*",
  UNDERSCORE: "_"
};
function rule(type, repeats = 3) {
  let realType;
  switch (type) {
    case "hyphens": {
      realType = RULE_CHAR.HYPHEN;
      break;
    }
    case "underscores": {
      realType = RULE_CHAR.UNDERSCORE;
      break;
    }
    case "asterisks": {
      realType = RULE_CHAR.ASTERISK;
      break;
    }
    default: {
      realType = RULE_CHAR.HYPHEN;
      break;
    }
  }
  return {
    toString() {
      return realType.repeat(repeats);
    }
  };
}
export {
  rule
};
